arguments.command:
python3 -c "
import json
print(json.loads('{\"a\":1,\"a\":2}'))
try:
    print(json.loads('[' + '1'*5000 + ']'))
except Exception as e:
    print('huge int ->', type(e).__name__, str(e)[:60])
print(json.loads('  [1, 2]  '))
try:
    print(json.loads('{} x'))
except Exception as e: print('trailing ->', type(e).__name__)
try:
    print(json.loads(''))
except Exception as e: print('empty ->', type(e).__name__)
try:
    print(json.loads(b'{\"a\": \"\\xff\"}'.decode('utf-8','replace'))
except Exception as e: print('bad utf8')
"
